 function updateLetterHighlight(forceLetter,center=!restoringCompass){const card=currentCard();const current=forceLetter||(card?catalog.letterOf(card.name):'');compassControl.sync(current,{center});const matchingLetters=compassControl.letters(),hasLetters=matchingLetters.length>0;const hint=browserScroll.querySelector('.diagram-compass-hint');if(hint)hint.textContent=!hasLetters?'Change the source filter to browse diagrams.':matchingLetters.length===1?'Only '+matchingLetters+' matches this filter':letterStrip.dataset.canBrowse==='true'?'Swipe letters · Tap to jump':'Tap a letter to jump';compassEmpty.hidden=hasLetters;pointer.hidden=!hasLetters;letterStrip.hidden=!hasLetters;if(card)letterStatus.textContent=catalog.letterOf(card.name)+' · '+card.name;else if(current)letterStatus.textContent=current;else letterStatus.textContent='';}
