 const oldCharacter=[...document.querySelectorAll('#field-reference .main-entry-card')].find(n=>n.querySelector('strong')?.textContent==='Character');if(oldCharacter){const replacement=card('Character','#character','gwent-r15/ivo.webp','Builds and Gear');replacement.className='main-entry-card';oldCharacter.replaceWith(replacement);}
