  const nav=make('nav',null,'diagram-detail-actions'),back=make('button','Return to Diagrams');back.type='button';back.dataset.diagramReturn='';back.onclick=()=>restoreOrigin(history.state?.diagramReturn);nav.append(back,a('All White Orchard diagrams','#gear-diagrams'));panel.append(nav);
