  const map=a(entry.kind==='fixed'?'Show diagram location':'Show primary seller location','#whiteorchard-map/'+entry.id,'primary-action');map.dataset.exactLocation='';panel.append(map);
  const label=make('label',null,'diagram-acquired'),check=make('input');check.type='checkbox';check.dataset.complete=entry.id;check.setAttribute('aria-label','Mark '+entry.name+' acquired');label.append(check,make('span','Diagram acquired in game'));panel.append(label,make('p','Records this diagram only. Quest objectives, documents and crafted equipment are separate. Existing whole-quest marks do not silently acquire individual diagrams.','quiet'));
  const undo=make('button','Undo last progress change');undo.type='button';undo.dataset.diagramUndo='';undo.onclick=()=>progressUI.undoLast();panel.append(undo);
